/* The pile: two edges drawn BEHIND the real card and BELOW it, inset and
 * stepped, so the card on top keeps its own padding and its own content
 * untouched. Below rather than above: a sheet peeking over the top edge
 * collides with whatever sits above the card, and a deck is read downwards
 * anyway. They are decoration — the count and the label carry the fact. */
.card-stack {
  position: relative;
  isolation: isolate;
  /* The pile takes the height of its row like any other card, and the card on
   * top takes the pile: without this the card stopped at its own text while the
   * sheets stayed pinned to the foot of the stretched cell, so the deck came
   * apart with a band of page showing between the card and its own edges
   * (owner, 23.08). */
  display: flex;
  flex-direction: column;
}
.card-stack > .card { flex: 1; }

/* THE ONE CARD IN THIS SYSTEM THAT WEARS AN OUTLINE.
 *
 * Everywhere else a card is separated by its fill, and on the page surface white
 * is separation enough. Not here: the pile draws its own edges directly under
 * the card, in the same white, so without a line of its own the top card melts
 * into the sheets under it and the whole thing reads as one smudged rectangle
 * (owner, 23.08, twice: "it blends in"). */
.card-stack > .card { border: 1px solid var(--border); }

/* The two controls sit together at the foot, after whatever the card carries.
 * `auto` would fight the content's own footer for the spare height and put it
 * in the middle of the card — this row is the last thing, at a step. */
.card-stack-actions {
  margin-block-start: var(--space-4);
  justify-content: flex-end;
  gap: var(--space-2);
}
.card-stack {
  /* Room under the card for the two sheets, so a stack in a grid does not
     overlap whatever comes after it. */
  padding-block-end: var(--space-4);
}
.card-stack::before,
.card-stack::after {
  content: "";
  position: absolute;
  /* A share, not a fixed inset: 16px off a 370px card is invisible, and the
   * pile read as one empty card under another (owner, 22.08). */
  /* EDGES, not cards. Each sheet shows 6px of itself: at 24px tall they read
   * as an empty card sitting under a full one, which is what the owner saw on
   * the patterns screen (22.08). A share of the width, not a fixed inset, so
   * the step is visible at 300px and at 800px alike. */
  inset-inline: 5%;
  inset-block-end: var(--space-2);
  block-size: var(--space-3);
  /* The sheets carry the STRONGER hairline: at --border they are white paper
   * on a near-white page and vanish (owner, 23.08: "it blends in"). The card on
   * top keeps the quiet border; the ones underneath have to survive being seen
   * edge-on. */
  border: 1px solid var(--border-strong, var(--border));
  border-block-start: none;
  border-end-start-radius: var(--card-radius);
  border-end-end-radius: var(--card-radius);
  background: var(--card);
  z-index: -1;
}
.card-stack::before {
  inset-inline: 10%;
  inset-block-end: 0;
  block-size: var(--space-3);
  opacity: 0.55;
}

.card-stack-count {
  position: absolute;
  inset-block-start: var(--space-3);
  inset-inline-end: var(--space-3);
  min-inline-size: var(--space-6);
  padding: 0 var(--space-2);
  border-radius: var(--radius-full);
  background: var(--muted);
  color: var(--muted-foreground);
  font-size: var(--font-xs);
  font-variant-numeric: tabular-nums;
  text-align: center;
  line-height: var(--space-6);
}

import "./CardStack.css";
import type { ReactNode } from "react";
import { cn } from "../lib/cn";
import { Button } from "../Button";
import { Card, CardMeta } from "../Card";

type Props = {
  /** How many there are in total, including the one on top. */
  count: number;
  /** Opening the pile. With `onNext` this is a named button; without it the
   *  whole card is the target, named for a screen reader by `label`. */
  onOpen: () => void;
  /** What the pile IS: "12 audits waiting on you". Read instead of the visual
   *  layering, which says nothing out loud. */
  label: string;
  /** The card on top — the usual card content, whatever family it belongs to. */
  children: ReactNode;
  /** Put the top card behind the pile and bring up the next one. Give it and
   *  the pile grows a pair of controls: the deck becomes something you can work
   *  through in place, which is the whole point of a pile you can see the edges
   *  of. The caller owns which card is on top, the way <Tabs> owns its value. */
  onNext?: () => void;
  /** The two button labels. Required with `onNext` — this package ships no UI
   *  text of its own. */
  nextLabel?: string;
  openLabel?: string;
  className?: string;
};

/** Many cards of one kind, shown as one: the top card, the count, and a way
 *  into the pile. An overview has room for one card per topic; when a topic has
 *  twenty instances the topic keeps its slot and the instances go behind it.
 *  Below about five, show them — a stack of three hides nothing and costs a
 *  click. With `onNext` the pile is also a queue you can work through in place.
 *
 * Copy: the label names the pile and the open control counts it — "Open all 9
 * findings". A count with no noun is a number nobody can act on.
 */
export function CardStack({ count, onOpen, label, children, onNext, nextLabel, openLabel, className }: Props) {
  const worked = Boolean(onNext && nextLabel && openLabel);
  /* The name of the pile goes wherever the pile's target is: on the card while
   * the card IS the target, on the group once two buttons are. Both at once is
   * the same name announced twice. */
  return (
    <div
      className={cn("card-stack", className)}
      data-count={count}
      role={worked ? "group" : undefined}
      aria-label={worked ? label : undefined}
    >
      {/* Two named controls or one big target, never both: a card that is itself
          a button swallows the click meant for the button inside it. */}
      <Card interactive={!worked} onClick={worked ? undefined : onOpen} aria-label={worked ? undefined : label}>
        {children}
        <span className="card-stack-count" aria-hidden="true">
          {count}
        </span>
        {worked && (
          <CardMeta className="card-stack-actions">
            <Button variant="secondary" size="sm" onClick={onNext}>
              {nextLabel}
            </Button>
            <Button size="sm" onClick={onOpen}>
              {openLabel}
            </Button>
          </CardMeta>
        )}
      </Card>
    </div>
  );
}
